### Charger RAGTruth en français
On lit le split **test** de la traduction française de RAGTruth, le jeu de la ligne « infidélité au contexte » de l'étude source. Chaque ligne contient :
- `prompt` : la consigne et les documents fournis au générateur ;
- `answer` : la réponse produite ;
- `labels` : les passages annotés comme hallucinés.

On ramène ces passages à une **étiquette au niveau réponse** : 1 (infidèle) dès qu'au moins un passage est annoté, 0 (fidèle) sinon. La traduction a pu déplacer les positions des passages, c'est pourquoi on ne les utilise pas.

def balanced_sample(df: pd.DataFrame, n_total: int, seed: int) -> pd.DataFrame:
    """Tire n_total exemples à parts égales entre les couples (tâche, classe), dans un ordre aléatoire."""
    groups = [group for _, group in df.groupby(["segment", "label"])]
    per_group = n_total // len(groups)
    parts = [group.sample(n=min(per_group, len(group)), random_state=seed) for group in groups]
    sample = pd.concat(parts)
    if len(sample) < n_total:  # division non exacte ou couple trop petit : on complète au hasard
        rest = df.drop(index=sample.index)
        sample = pd.concat([sample, rest.sample(n=min(n_total - len(sample), len(rest)), random_state=seed)])
    return sample.sample(frac=1.0, random_state=seed).reset_index(drop=True)


def describe_splits(calibration: pd.DataFrame, evaluation: pd.DataFrame) -> pd.DataFrame:
    """Effectifs par classe et longueurs médianes (en caractères) des deux lots."""
    rows = []
    for name, df in [("calibration", calibration), ("évaluation", evaluation)]:
        rows.append({
            "lot": name, "exemples": len(df),
            "infidèles": int(df["label"].sum()), "fidèles": int((df["label"] == 0).sum()),
            "source (car., médiane)": int(df["source_text"].str.len().median()),
            "réponse (car., médiane)": int(df["answer"].str.len().median()),
        })
    return pd.DataFrame(rows).set_index("lot")


if PHASE == "public":
    sample = balanced_sample(corpus, N_TOTAL, SEED)
    calibration_df, evaluation_df = train_test_split(
        sample, train_size=N_CALIBRATION, stratify=sample["segment"] + "-" + sample["label"].astype(str), random_state=SEED
    )
    calibration_df = calibration_df.reset_index(drop=True)
    evaluation_df = evaluation_df.reset_index(drop=True)  # ordre aléatoire conservé
    DATASET_INFO = {"name": DATASET_ID, "config": DATASET_CONFIG, "split": DATASET_SPLIT}
    display(describe_splits(calibration_df, evaluation_df))

def shorten(df: pd.DataFrame, width: int = 160) -> pd.DataFrame:
    """Copie du tableau dont les textes longs sont coupés à `width` caractères, pour l'affichage."""
    out = df.copy()
    for column in ("source_text", "answer"):
        if column in out:
            out[column] = out[column].str.slice(0, width) + "…"
    return out


if PHASE == "public":
    preview(shorten(evaluation_df[["segment", "label", "source_text", "answer"]]), n=3)

### Données internes : colonnes attendues et jeu factice
La phase interne lit six colonnes : passages récupérés, question, réponse, étiquette humaine d'infidélité, thème et date de génération. Pour vérifier que tout s'exécute sans exposer de vraies données, `make_fake_data` fabrique un jeu **factice** au même format :
- des extraits de conditions (carte de paiement, virement, compte…) ;
- une réponse fidèle, ou rendue infidèle par une **valeur modifiée** (contradiction) ou par une **affirmation inventée** ;
- des dates étalées sur neuf mois, pour permettre le découpage temporel.

Ce même générateur sert, dans les deux phases, de **contrôle positif** à l'analyse : des erreurs grossières qu'un juge utile doit repérer.

MAX_INPUT_TOKENS = by_scale(reduced=384, full=4096)  # longueur maximale d'un prompt complet (tokens)
TRUNCATION_MARK = " […]"  # signale au juge qu'un texte a été coupé
PROMPT_OVERHEAD_TOKENS = max(
    len(encode_prompt(build_messages("", "", ("H", "N"), instruction)))
    for instruction in (TYPED_INSTRUCTION, GENERATIVE_INSTRUCTION, GENERATIVE_JSON_INSTRUCTION)
) + 16  # marge : marques de troncature et effets de bord du découpage en tokens


def truncate_inputs(source: str, answer: str) -> tuple[str, str, bool]:
    """Coupe réponse puis documents (début conservé) pour tenir dans MAX_INPUT_TOKENS ; rend aussi un indicateur de coupe."""
    budget = MAX_INPUT_TOKENS - PROMPT_OVERHEAD_TOKENS
    source_ids = tokenizer.encode(source, add_special_tokens=False)
    answer_ids = tokenizer.encode(answer, add_special_tokens=False)
    answer_keep = min(len(answer_ids), budget // 2)  # la réponse prend au plus la moitié du budget
    source_keep = min(len(source_ids), budget - answer_keep)
    if answer_keep < len(answer_ids):
        answer = tokenizer.decode(answer_ids[:answer_keep]) + TRUNCATION_MARK
    if source_keep < len(source_ids):
        source = tokenizer.decode(source_ids[:source_keep]) + TRUNCATION_MARK
    return source, answer, (answer_keep < len(answer_ids)) or (source_keep < len(source_ids))


content_budget = MAX_INPUT_TOKENS - PROMPT_OVERHEAD_TOKENS
assert content_budget >= 128, "Budget trop faible pour les documents et la réponse"
print(f"Gabarit et consignes : {PROMPT_OVERHEAD_TOKENS} tokens ; reste {content_budget} tokens pour documents et réponse.")
if PHASE == "public":
    prompt_lengths = pd.Series([len(encode_prompt(build_messages(text, answer, ("H", "N"), TYPED_INSTRUCTION)))
                                for text, answer in zip(sample["source_text"], sample["answer"])])
    print(f"Prompts de l'échantillon : médiane {prompt_lengths.median():.0f} tokens, maximum {prompt_lengths.max()} ; "
          f"{(prompt_lengths > MAX_INPUT_TOKENS).sum()} sur {len(prompt_lengths)} au-delà de {MAX_INPUT_TOKENS}.")

VERDICT_PATTERN = re.compile(r"verdict\W*([HN])\b", re.IGNORECASE)
CONFIDENCE_PATTERN = re.compile(r"confiance\W*(\d+(?:[.,]\d+)?)\s*(%?)", re.IGNORECASE)


def to_confidence(value, percent: bool = False) -> float | None:
    """Nombre en confiance dans [0, 1] (les pourcentages sont ramenés sur 1) ; None si invalide."""
    try:
        number = float(str(value).replace(",", "."))
    except (TypeError, ValueError):
        return None
    if percent or number > 1:
        number /= 100
    return number if 0.0 <= number <= 1.0 else None


def parse_generative_output(text: str) -> tuple[int | None, float | None]:
    """Verdict (1 = infidèle, 0 = fidèle, None si illisible) et confiance (None si illisible) d'un texte généré."""
    verdict_match = VERDICT_PATTERN.search(text)
    verdict = None if verdict_match is None else int(verdict_match.group(1).upper() == "H")
    confidence_match = CONFIDENCE_PATTERN.search(text)
    if confidence_match is None:
        return verdict, None
    return verdict, to_confidence(confidence_match.group(1), percent=confidence_match.group(2) == "%")


def parse_service_reply(reply) -> tuple[int | None, float | None]:
    """Verdict et confiance d'une réponse JSON décodée du service (None si absente ou invalide)."""
    if not isinstance(reply, dict):
        return None, None
    verdict = {"H": 1, "N": 0}.get(str(reply.get("verdict", "")).strip().upper())
    return verdict, to_confidence(reply.get("confidence"))


# Contrôles sur des sorties construites à la main (dont le format du service)
assert parse_generative_output("Verdict : H\nConfiance : 0,85") == (1, 0.85)
assert parse_generative_output("**Verdict :** N\n**Confiance :** 90 %") == (0, 0.9)
assert parse_generative_output("Je ne peux pas répondre.") == (None, None)
assert parse_service_reply({"verdict": "n", "confidence": 0.7}) == (0, 0.7)
assert parse_service_reply(None) == (None, None)

MAX_NEW_TOKENS = 24  # le verdict et la confiance tiennent en une quinzaine de tokens
GENERATIVE_SCHEMA = {
    "type": "object",
    "properties": {"verdict": {"type": "string", "enum": ["H", "N"]}, "confidence": {"type": "number"}},
    "required": ["verdict", "confidence"],
    "additionalProperties": False,
}
SERVICE_ERRORS: list[str] = []  # types d'erreurs des appels au service (phase interne)


@torch.inference_mode()
def generate_local(messages: list[dict]) -> str:
    """Génération gloutonne locale limitée à MAX_NEW_TOKENS ; rend le texte produit."""
    input_ids = torch.tensor([encode_prompt(messages)], device=COMPUTE_DEVICE)
    output = model.generate(
        input_ids, attention_mask=torch.ones_like(input_ids), max_new_tokens=MAX_NEW_TOKENS,
        do_sample=False, temperature=None, top_p=None, top_k=None,
        pad_token_id=tokenizer.pad_token_id if tokenizer.pad_token_id is not None else tokenizer.eos_token_id,
    )
    return tokenizer.decode(output[0, input_ids.shape[1]:], skip_special_tokens=True)


def ask_service(messages: list[dict]):
    """Appel au service LLM avec sortie structurée ; None (compté comme illisible) si l'appel échoue."""
    try:
        return llm_chat(messages, schema=GENERATIVE_SCHEMA, temperature=0.0, max_tokens=64)
    except Exception as error:  # une panne isolée ne doit pas interrompre l'évaluation ; elle est comptée
        SERVICE_ERRORS.append(type(error).__name__)
        return None

### Du texte au verdict chiffré
Chaque sortie devient quatre valeurs :
- le **verdict** (1, 0 ou −1 si illisible) ;
- la **confiance** dans ce verdict ;
- $P(\text{infidèle})$, qui vaut la confiance si le verdict est H et $1 - \text{confiance}$ sinon ;
- un indicateur d'**échec d'analyse**.

Ces quatre champs sont les mêmes pour la décision typée, ce qui permet de calculer les métriques de la même façon pour les deux approches.

def outcome(verdict: int | None, confidence: float | None) -> dict:
    """Verdict, confiance, P(infidèle) et échec d'analyse ; un verdict illisible devient −1, compté comme erreur."""
    if verdict is None:
        return {"verdict": -1, "confidence": 0.5, "p_unfaithful": 0.5, "parse_failed": True}
    failed = confidence is None
    confidence = 0.5 if confidence is None else float(confidence)
    p_unfaithful = confidence if verdict == 1 else 1.0 - confidence
    return {"verdict": verdict, "confidence": confidence, "p_unfaithful": p_unfaithful, "parse_failed": failed}


def judge_generative(row) -> dict:
    """Juge génératif sur un exemple : modèle local en phase publique, service LLM en phase interne."""
    source, answer, truncated = truncate_inputs(row.source_text, row.answer)
    if PHASE == "public":
        raw_output = generate_local(build_messages(source, answer, ("H", "N"), GENERATIVE_INSTRUCTION))
        verdict, confidence = parse_generative_output(raw_output)
    else:
        reply = ask_service(build_messages(source, answer, ("H", "N"), GENERATIVE_JSON_INSTRUCTION))
        verdict, confidence = parse_service_reply(reply)
        raw_output = ""  # rien n'est conservé des sorties sur données internes
    return {**outcome(verdict, confidence), "truncated": truncated, "raw_output": raw_output}

@torch.inference_mode()
def option_log_odds(sequences: list[list[int]], shared: int) -> list[float]:
    """logit(H) − logit(N) au dernier token de chaque prompt ; le préfixe commun passe une seule fois (cache KV)."""
    prefix = torch.tensor([sequences[0][:shared]], device=COMPUTE_DEVICE)
    cache = model(input_ids=prefix, use_cache=True).past_key_values
    values = []
    for sequence in sequences:
        suffix = torch.tensor([sequence[shared:]], device=COMPUTE_DEVICE)
        # copie du cache : la seconde fin ne doit pas voir les tokens de la première
        logits = model(input_ids=suffix, past_key_values=copy.deepcopy(cache), use_cache=True).logits[0, -1].float()
        values.append(float(logits[OPTION_IDS["H"]] - logits[OPTION_IDS["N"]]))
    return values


def judge_typed(row) -> dict:
    """Score brut de la décision typée : moyenne des log-odds des deux ordres (verdict provisoire au seuil 0)."""
    sequences, shared, truncated = typed_sequences(row)
    log_odds = option_log_odds(sequences, shared)
    score = float(np.mean(log_odds))
    return {"score": score, "log_odds_order_hn": log_odds[0], "log_odds_order_nh": log_odds[1],
            "verdict": int(score > 0), "truncated": truncated}

TOP_TOKENS = 5  # nombre de tokens les plus probables affichés


@torch.inference_mode()
def next_token_distribution(sequence: list[int]) -> torch.Tensor:
    """Distribution (softmax sur tout le vocabulaire) du token qui suit le prompt."""
    logits = model(input_ids=torch.tensor([sequence], device=COMPUTE_DEVICE)).logits[0, -1].float()
    return torch.softmax(logits, dim=-1)


probe_source, probe_answer, _ = truncate_inputs(probe_row.source_text, probe_row.answer)
probe_messages = build_messages(probe_source, probe_answer, OPTION_ORDERS[0], TYPED_INSTRUCTION)
probe_ids = encode_prompt(probe_messages)
for letter, token_id in OPTION_IDS.items():
    with_letter = tokenizer(render_prompt(probe_messages) + letter, add_special_tokens=False)["input_ids"]
    assert with_letter == probe_ids + [token_id], f"« {letter} » n'est pas le premier token de la réponse"
next_probabilities = next_token_distribution(probe_ids)
option_mass = float(next_probabilities[list(OPTION_IDS.values())].sum())
print(f"Masse de probabilité sur H et N au premier token de réponse : {option_mass:.1%}")
top = torch.topk(next_probabilities, TOP_TOKENS)
pd.DataFrame({
    "token": [repr(tokenizer.decode([int(index)])) for index in top.indices],
    "probabilité": top.values.cpu().numpy(),
}).round(4)

### Température et décalage : une régression logistique régularisée et bornée
On ajuste $P(H) = \sigma((s - b)/T)$ en minimisant la **log-vraisemblance négative** sur le lot de calibration, avec trois garde-fous :
- **T bornée** entre 0,05 et 50 : une température infinie rendrait $P(H)$ constante, une température nulle la saturerait à 0 ou 1 ;
- une **pénalité L2** sur la pente $1/T$ du score standardisé (comme une régression logistique classique), et un décalage $b$ limité à l'étendue des scores ;
- un indicateur « T à une borne » : il signale un score sans signal (borne haute) ou trop tranché (borne basse).

Attention : une **T très grande** aplatit $P(H)$ vers une constante. L'ECE devient alors basse **sans information** : c'est pourquoi l'évaluation compare aussi au prédicteur constant. L'optimiseur est **L-BFGS-B**, qui respecte ces bornes.

def balanced_accuracy(labels: np.ndarray, verdicts: np.ndarray) -> float:
    """Moyenne des taux de bonnes décisions par classe présente ; un verdict illisible (−1) est une erreur."""
    recalls = [np.mean(verdicts[labels == value] == value) for value in np.unique(labels)]
    return float(np.mean(recalls)) if recalls else float("nan")


def false_negative_rate(labels: np.ndarray, verdicts: np.ndarray) -> float:
    """Part des réponses infidèles que le juge ne signale pas."""
    positives = labels == 1
    return float(np.mean(verdicts[positives] != 1)) if positives.any() else float("nan")

ECE_BINS = 10  # intervalles de confiance de largeur 0,1 (ECE et diagramme de fiabilité)
HIGH_CONFIDENCE = 0.9  # seuil de « grande confiance » repris de l'étude source
CALIBRATION_PREVALENCE = float(calibration_df["label"].mean())  # P(H) du prédicteur constant de référence


def confidence_bins(confidence: np.ndarray) -> np.ndarray:
    """Numéro d'intervalle (0 à ECE_BINS − 1) de chaque confiance."""
    edges = np.linspace(0.0, 1.0, ECE_BINS + 1)
    return np.clip(np.digitize(confidence, edges[1:-1], right=True), 0, ECE_BINS - 1)


def expected_calibration_error(confidence: np.ndarray, correct: np.ndarray) -> float:
    """Moyenne pondérée de |taux de bonnes décisions − confiance moyenne| ; NaN si la confiance est constante."""
    if len(confidence) == 0 or np.ptp(confidence) == 0:
        return float("nan")
    bins = confidence_bins(confidence)
    gaps = [np.mean(bins == b) * abs(correct[bins == b].mean() - confidence[bins == b].mean())
            for b in range(ECE_BINS) if np.any(bins == b)]
    return float(np.sum(gaps))


def brier_score(p_unfaithful: np.ndarray, labels: np.ndarray) -> float:
    """Erreur quadratique moyenne entre P(infidèle) et l'étiquette 0/1."""
    return float(np.mean((p_unfaithful - labels) ** 2))


def brier_skill(p_unfaithful: np.ndarray, labels: np.ndarray) -> float:
    """1 − Brier / Brier du prédicteur constant (prévalence de calibration) ; ≤ 0 : pas mieux qu'une constante."""
    constant = brier_score(np.full(len(labels), CALIBRATION_PREVALENCE), labels)
    return float(1.0 - brier_score(p_unfaithful, labels) / constant) if constant > 0 else float("nan")


def confidence_auroc(confidence: np.ndarray, correct: np.ndarray) -> float:
    """Probabilité qu'une bonne décision ait une confiance plus haute qu'une erreur ; NaN si confiance ou issue constante."""
    if len(confidence) == 0 or np.ptp(confidence) == 0 or correct.min() == correct.max():
        return float("nan")
    return float(roc_auc_score(correct, confidence))

N_BOOTSTRAP = 1000  # rééchantillonnages pour les intervalles de confiance
DEFERRAL_FRACTION = 0.25  # part visée des cas les moins sûrs renvoyés à un second avis


def deferral_mask(confidence: np.ndarray) -> np.ndarray:
    """Cas gardés : confiance strictement au-dessus du quantile 25 % (seuil calculé sans étiquette)."""
    return confidence > np.quantile(confidence, DEFERRAL_FRACTION)


def approach_arrays(outputs: pd.DataFrame) -> dict[str, np.ndarray]:
    """Tableaux numpy d'une approche : verdicts, confiance, P(infidèle), justesse, échecs, cas gardés."""
    verdicts = outputs["verdict"].to_numpy().astype(int)
    confidence = outputs["confidence"].to_numpy().astype(float)
    return {
        "verdicts": verdicts, "confidence": confidence,
        "p_unfaithful": outputs["p_unfaithful"].to_numpy().astype(float),
        "correct": (verdicts == y_true).astype(float),
        "parse_failed": outputs["parse_failed"].to_numpy().astype(float),
        "kept": deferral_mask(confidence),
    }

### Un dictionnaire de métriques commun
Chaque métrique est une fonction de deux arguments : les tableaux d'une approche, et des **indices** d'exemples. Le bootstrap pourra ainsi les recalculer sur n'importe quel rééchantillonnage. On y trouve :
- la **BAcc après renvoi**, mesurée sur les seuls cas gardés ;
- le **Brier skill score**, qui compare la probabilité au prédicteur constant ;
- le **taux d'échec d'analyse**, sans objet pour la décision typée, qui ne génère rien : il vaudra `None` pour elle.

Les libellés lisibles de chaque clé sont regroupés dans `METRIC_LABELS`.

def evaluate(arrays: dict, not_applicable: tuple = ()) -> tuple[dict, dict]:
    """Valeur et IC à 95 % (bootstrap) de chaque métrique ; None si sans objet ou non définie."""
    indices = np.arange(n_evaluated)
    metrics, ci95 = {}, {}
    for key, metric_fn in METRICS.items():
        if key in not_applicable:
            metrics[key] = None
            continue
        value, low, high = bootstrap_ci(
            indices, indices, lambda sampled, _same, fn=metric_fn: fn(arrays, np.asarray(sampled, dtype=int)),
            n=N_BOOTSTRAP, seed=SEED,
        )
        metrics[key] = float(value) if np.isfinite(value) else None
        if metrics[key] is not None and np.isfinite(low) and np.isfinite(high):
            ci95[key] = [float(low), float(high)]
    return metrics, ci95


reference_metrics, reference_ci = evaluate(reference_arrays)
typed_metrics, typed_ci = evaluate(typed_arrays, not_applicable=("parse_failure_rate",))
pd.DataFrame({"Juge génératif": reference_metrics, "Décision typée": typed_metrics}).round(4)

### Confronter l'hypothèse, sous condition d'éligibilité
Les trois critères sont tranchés sur les **intervalles appariés**, pas sur les seules valeurs ponctuelles :
- **non-infériorité** : borne basse de l'écart de BAcc ≥ −2 points (tolérance `BACC_TOLERANCE`) ;
- **calibration** : ECE typée ≤ 70 % de l'ECE générative **et** borne haute de l'écart d'ECE < 0 ;
- **classement** : borne basse de l'écart de conf-AUROC > 0.

Si un juge n'est pas éligible, chaque critère est **non concluant**, quelle que soit sa valeur.

BACC_TOLERANCE = 0.02  # baisse d'exactitude équilibrée tolérée par l'hypothèse : 2 points
ECE_REDUCTION = 0.30  # baisse relative d'ECE visée par l'hypothèse


def is_finite(*values) -> bool:
    """Vrai si toutes les valeurs sont définies et finies."""
    return all(value is not None and np.isfinite(value) for value in values)


def criterion(condition: bool | None) -> str:
    """Statut d'un critère : non concluant sans juges éligibles, non tranché si une métrique manque."""
    if not BOTH_ELIGIBLE:
        return "non concluant (au moins un juge au niveau du hasard)"
    if condition is None:
        return "non tranché (métrique non définie)"
    return "atteint" if condition else "non atteint"


_, bacc_low, _ = PAIRED["balanced_accuracy"]
_, _, ece_high = PAIRED["expected_calibration_error"]
_, auroc_low, _ = PAIRED["conf_auroc"]
ece_reference, ece_typed = reference_metrics["expected_calibration_error"], typed_metrics["expected_calibration_error"]
HYPOTHESIS_CRITERIA = {
    "BAcc non inférieure (borne basse de l'écart apparié ≥ −2 points)":
        criterion(bool(bacc_low >= -BACC_TOLERANCE) if is_finite(bacc_low) else None),
    "ECE inférieure d'au moins 30 % (et écart apparié < 0)":
        criterion(bool(ece_typed <= (1 - ECE_REDUCTION) * ece_reference and ece_high < 0)
                  if is_finite(ece_reference, ece_typed, ece_high) else None),
    "conf-AUROC supérieure (borne basse de l'écart apparié > 0)":
        criterion(bool(auroc_low > 0) if is_finite(auroc_low) else None),
}
if not BOTH_ELIGIBLE:
    HYPOTHESIS_VERDICT = "Test non concluant : au moins un juge ne fait pas mieux que le hasard ; aucune conclusion sur la calibration ni sur le tri du trafic."
elif all(status == "atteint" for status in HYPOTHESIS_CRITERIA.values()):
    HYPOTHESIS_VERDICT = "Hypothèse soutenue : les trois critères sont atteints, intervalles appariés compris."
else:
    HYPOTHESIS_VERDICT = "Hypothèse non soutenue : au moins un critère n'est pas atteint."
print(HYPOTHESIS_VERDICT)
pd.Series(HYPOTHESIS_CRITERIA, name="statut").to_frame()

def constant_judge_metrics(prevalence: float, labels: np.ndarray) -> dict:
    """Juge trivial : toujours la même probabilité P(H) = prévalence de calibration, donc le même verdict."""
    verdict = int(prevalence > 0.5)
    confidence = max(prevalence, 1.0 - prevalence)
    correct = (labels == verdict).astype(float)
    return {"BAcc": balanced_accuracy(labels, np.full(len(labels), verdict)),
            "ECE": abs(float(correct.mean()) - confidence),  # un seul intervalle de confiance
            "Brier": brier_score(np.full(len(labels), prevalence), labels),
            "confiance min": confidence, "confiance max": confidence}


baseline_rows = {"Prédicteur constant": constant_judge_metrics(CALIBRATION_PREVALENCE, y_true)}
for name, arrays, _ in APPROACH_VIEWS:
    baseline_rows[name] = {
        "BAcc": balanced_accuracy(y_true, arrays["verdicts"]),
        "ECE": expected_calibration_error(arrays["confidence"], arrays["correct"]),
        "Brier": brier_score(arrays["p_unfaithful"], y_true),
        "confiance min": float(arrays["confidence"].min()), "confiance max": float(arrays["confidence"].max()),
    }
pd.DataFrame.from_dict(baseline_rows, orient="index").round(4)

### Contrôle positif : le juge voit-il une erreur grossière ?
Pour savoir si un échec vient du **modèle** ou du **protocole**, on soumet les deux juges, avec exactement le même code, à des cas **faciles** :
- des extraits courts et synthétiques (`make_fake_data`) dont la réponse est fidèle, ou contient une valeur modifiée ou une phrase inventée ;
- les entrées sont courtes, donc jamais tronquées ;
