def bacc_interval(labels: np.ndarray, verdicts: np.ndarray) -> tuple[float, float, float]:
    """BAcc et IC à 95 % par bootstrap ; NaN si le groupe ne contient pas les deux classes."""
    if np.unique(labels).size < 2:
        return float("nan"), float("nan"), float("nan")
    return bootstrap_ci(labels, verdicts, balanced_accuracy, n=N_BOOTSTRAP, seed=SEED)


def diagnostic_row(group: str, judge: str, labels: np.ndarray, verdicts: np.ndarray, scores: np.ndarray) -> dict:
    """Effectif, BAcc avec IC et AUROC du score P(H) d'un juge sur un groupe d'exemples."""
    value, low, high = bacc_interval(labels, verdicts)
    separable = np.unique(labels).size == 2 and np.ptp(scores) > 0
    return {"groupe": group, "juge": judge, "exemples": len(labels), "BAcc": value, "IC bas": low,
            "IC haut": high, "AUROC du score": roc_auc_score(labels, scores) if separable else float("nan")}


